import{_ as e,c as a,o as r,a1 as n,eB as t}from"./chunks/framework.CkSEW8EO.js";const m=JSON.parse('{"title":"Hur fungerar en webbläsare? (Google Chrome)","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"web1/3-web/how-work-web-browser.md","filePath":"web1/3-web/how-work-web-browser.md"}'),i={name:"web1/3-web/how-work-web-browser.md"},l=n('<h1 id="hur-fungerar-en-webblasare-google-chrome" tabindex="-1">Hur fungerar en webbläsare? (Google Chrome) <a class="header-anchor" href="#hur-fungerar-en-webblasare-google-chrome" aria-label="Permalink to &quot;Hur fungerar en webbläsare? (Google Chrome)&quot;">​</a></h1><p>En webbläsare är ett program som används för att visa webbsidor på internet. Google Chrome är en av de mest populära webbläsarna och är utvecklad av Google. Men hur fungerar den egentligen?</p><p align="center"><img src="'+t+'" alt="webbläsare-bild"></p><h2 id="_1-vad-hander-nar-du-skriver-en-webbadress" tabindex="-1">1. Vad händer när du skriver en webbadress? <a class="header-anchor" href="#_1-vad-hander-nar-du-skriver-en-webbadress" aria-label="Permalink to &quot;1. Vad händer när du skriver en webbadress?&quot;">​</a></h2><p>När du skriver in en webbadress (t.ex. www.google.se) i adressfältet och trycker på Enter händer flera saker:</p><ol><li>DNS-uppslagning – Webbläsaren översätter webbadressen till en IP-adress. Detta görs genom en DNS-server (Domain Name System).</li><li>HTTP/HTTPS-förfrågan – Webbläsaren skickar en begäran (request) till webbservern där webbsidan finns lagrad.</li><li>Serverns svar – Webbservern svarar med HTML, CSS, JavaScript och andra resurser som behövs för att visa sidan.</li><li>Rendering (visning av sidan) – Webbläsaren tolkar koden och visar sidan på skärmen.</li></ol><br><h2 id="_2-viktiga-delar-i-en-webblasare" tabindex="-1">2. Viktiga delar i en webbläsare <a class="header-anchor" href="#_2-viktiga-delar-i-en-webblasare" aria-label="Permalink to &quot;2. Viktiga delar i en webbläsare&quot;">​</a></h2><h3 id="rendering-engine-renderingsmotor" tabindex="-1">Rendering Engine (Renderingsmotor) <a class="header-anchor" href="#rendering-engine-renderingsmotor" aria-label="Permalink to &quot;Rendering Engine (Renderingsmotor)&quot;">​</a></h3><p>Renderingsmotorn ansvarar för att rita upp webbsidan på skärmen. Google Chrome använder Blink, som är en del av webbläsarprojektet Chromium.</p><h3 id="javascript-engine-javascript-motor" tabindex="-1">JavaScript Engine (JavaScript-motor) <a class="header-anchor" href="#javascript-engine-javascript-motor" aria-label="Permalink to &quot;JavaScript Engine (JavaScript-motor)&quot;">​</a></h3><p>JavaScript är ett programmeringsspråk som används på webbsidor för att göra dem interaktiva. Chrome använder en JavaScript-motor som heter V8, vilket gör att webbsidor kan köra JavaScript snabbt.</p><h3 id="user-interface-anvandargranssnitt" tabindex="-1">User Interface (Användargränssnitt) <a class="header-anchor" href="#user-interface-anvandargranssnitt" aria-label="Permalink to &quot;User Interface (Användargränssnitt)&quot;">​</a></h3><p>Användargränssnittet är det du ser och interagerar med i webbläsaren, t.ex.:</p><ul><li>Adressfältet (där du skriver in webbadresser)</li><li>Tillbaka- och framåtknappar</li><li>Bokmärken</li><li>Flikar</li></ul><h3 id="networking-natverkshantering" tabindex="-1">Networking (Nätverkshantering) <a class="header-anchor" href="#networking-natverkshantering" aria-label="Permalink to &quot;Networking (Nätverkshantering)&quot;">​</a></h3><p>Den här delen hanterar kommunikationen med webbservrar, t.ex. genom protokollen HTTP och HTTPS.</p><h3 id="storage-lagring" tabindex="-1">Storage (Lagring) <a class="header-anchor" href="#storage-lagring" aria-label="Permalink to &quot;Storage (Lagring)&quot;">​</a></h3><p>Webbläsaren kan lagra data på din dator, t.ex.:</p><ul><li>Cookies – Små filer med information om dig och din surfning.</li><li>LocalStorage &amp; SessionStorage – Sätt att spara data i webbläsaren.</li><li>Cache – Temporära filer för att snabba upp laddning av webbsidor.</li></ul><br><h2 id="_3-viktiga-begrepp-att-kanna-till" tabindex="-1">3. Viktiga begrepp att känna till <a class="header-anchor" href="#_3-viktiga-begrepp-att-kanna-till" aria-label="Permalink to &quot;3. Viktiga begrepp att känna till&quot;">​</a></h2><h3 id="http-https" tabindex="-1">HTTP &amp; HTTPS <a class="header-anchor" href="#http-https" aria-label="Permalink to &quot;HTTP &amp; HTTPS&quot;">​</a></h3><ul><li>HTTP (Hypertext Transfer Protocol) – Ett protokoll för att överföra webbsidor.</li><li>HTTPS (Hypertext Transfer Protocol Secure) – En säkrare version av HTTP som använder SSL/TLS för kryptering.</li></ul><h3 id="html-css-och-javascript" tabindex="-1">HTML, CSS och JavaScript <a class="header-anchor" href="#html-css-och-javascript" aria-label="Permalink to &quot;HTML, CSS och JavaScript&quot;">​</a></h3><ul><li>HTML (HyperText Markup Language) – Strukturen på webbsidan (t.ex. rubriker, text, bilder).</li><li>CSS (Cascading Style Sheets) – Design och layout (t.ex. färger, typsnitt, placering).</li><li>JavaScript – Gör sidan interaktiv (t.ex. knappar, animationer).</li></ul><h3 id="dom-document-object-model" tabindex="-1">DOM (Document Object Model) <a class="header-anchor" href="#dom-document-object-model" aria-label="Permalink to &quot;DOM (Document Object Model)&quot;">​</a></h3><p>Webbläsaren skapar en DOM-struktur av HTML-koden, vilket gör att JavaScript kan ändra innehållet på sidan dynamiskt.</p><h3 id="cache" tabindex="-1">Cache <a class="header-anchor" href="#cache" aria-label="Permalink to &quot;Cache&quot;">​</a></h3><p>Webbläsaren sparar vissa filer lokalt (t.ex. bilder och stilmallar) för att göra laddningen snabbare nästa gång du besöker samma sida.</p><h3 id="cookies" tabindex="-1">Cookies <a class="header-anchor" href="#cookies" aria-label="Permalink to &quot;Cookies&quot;">​</a></h3><p>Små textfiler som lagras i webbläsaren och innehåller information, t.ex. inloggningsuppgifter eller inställningar.</p><h3 id="flikar-processhantering" tabindex="-1">Flikar &amp; Processhantering <a class="header-anchor" href="#flikar-processhantering" aria-label="Permalink to &quot;Flikar &amp; Processhantering&quot;">​</a></h3><p>Google Chrome skapar en egen process för varje flik, vilket gör att om en flik kraschar påverkar det inte de andra.</p><h3 id="extensions-tillagg" tabindex="-1">Extensions (Tillägg) <a class="header-anchor" href="#extensions-tillagg" aria-label="Permalink to &quot;Extensions (Tillägg)&quot;">​</a></h3><p>Chrome låter dig installera tillägg som förbättrar webbläsaren, t.ex. annonsblockerare eller lösenordshanterare.</p><h3 id="devtools-utvecklarverktyg" tabindex="-1">DevTools (Utvecklarverktyg) <a class="header-anchor" href="#devtools-utvecklarverktyg" aria-label="Permalink to &quot;DevTools (Utvecklarverktyg)&quot;">​</a></h3><p>Genom att trycka på F12 eller Ctrl + Shift + I kan du öppna utvecklarverktygen, där du kan:</p><ul><li>Inspektera HTML och CSS</li><li>Debugga JavaScript</li><li>Se nätverksförfrågningar</li></ul><br><h2 id="_4-hur-optimerar-chrome-prestandan" tabindex="-1">4. Hur optimerar Chrome prestandan? <a class="header-anchor" href="#_4-hur-optimerar-chrome-prestandan" aria-label="Permalink to &quot;4. Hur optimerar Chrome prestandan?&quot;">​</a></h2><ul><li>Multi-processarkitektur – Varje flik körs i en egen process.</li><li>GPU-acceleration – Använder grafikkortet för att snabbare rita upp sidor.</li><li>Lazy Loading – Laddar bara bilder och innehåll när det behövs.</li><li>Preloading &amp; Prefetching – Webbläsaren laddar vissa resurser i förväg för att göra sidan snabbare.</li></ul><br><h2 id="sammanfattning" tabindex="-1">Sammanfattning <a class="header-anchor" href="#sammanfattning" aria-label="Permalink to &quot;Sammanfattning&quot;">​</a></h2><p>Google Chrome är en avancerad webbläsare som gör det möjligt att surfa på internet genom att:</p><ol><li>Hämta och tolka webbsidor med hjälp av HTML, CSS och JavaScript.</li><li>Använda renderingsmotorn Blink för att visa sidorna.</li><li>Köra JavaScript snabbt med hjälp av V8-motorn.</li><li>Hantera nätverk, lagring och säkerhet för en snabb och säker upplevelse.</li></ol><br><p>😎 👊 👍</p>',48),o=[l];function s(d,h,b,g,c,p){return r(),a("div",null,o)}const u=e(i,[["render",s]]);export{m as __pageData,u as default};
